cd /home/edumg/hackathon-dopamine-worktrees/eduardo-beija-flor/site/web && python3 - <<'EOF'
p='src/estilo.css'
s=open(p).read()
old=".logo img { height: 1.45em; width: auto; }\n"
assert old in s
new=old+""".logo .beija-flor { height: 1.45em; width: auto; overflow: visible; }

/* Beija-flor animado da capa (Logo animado). Os transform-origin estão em unidades do viewBox do SVG:
   raiz de cada asa, dobradiça do bico, pescoço e base da cauda. */
.beija-flor .bf-corpo { transform-origin: 100px 120px; animation: bf-flutuar 2.6s ease-in-out infinite; }
.beija-flor .bf-rastros { animation: bf-rastros 1.3s ease-in-out infinite; }
.beija-flor .bf-cauda { transform-origin: 80px 146px; animation: bf-cauda 2.6s ease-in-out infinite; }
.beija-flor .bf-asa { animation: bf-asa 0.075s ease-in-out infinite alternate; }
.beija-flor .bf-asa-frente, .beija-flor .bf-borrao { transform-origin: 106px 114px; }
.beija-flor .bf-asa-tras { transform-origin: 95px 110px; animation-delay: -0.03s; }
.beija-flor .bf-borrao { opacity: 0.22; }
.beija-flor .bf-borrao-cima { transform: rotate(14deg); }
.beija-flor .bf-borrao-baixo { transform: rotate(-44deg) scale(0.9); }
.beija-flor .bf-cabeca { transform-origin: 138px 104px; animation: bf-cabeca 3.6s ease-in-out infinite; }
.beija-flor .bf-bico-baixo { transform-origin: 166px 86px; animation: bf-bico-baixo 3.6s ease-in-out infinite; }
.beija-flor .bf-bico-cima { transform-origin: 165px 80px; animation: bf-bico-cima 3.6s ease-in-out infinite; }
.inicio.pausado .beija-flor * { animation-play-state: paused; }

@keyframes bf-flutuar {
  0%, 100% { transform: translateY(0) rotate(0); }
  50% { transform: translateY(-6px) rotate(-2.5deg); }
}
@keyframes bf-rastros {
  0%, 100% { transform: translateX(0); opacity: 1; }
  50% { transform: translateX(-5px); opacity: 0.45; }
}
@keyframes bf-cauda {
  0%, 100% { transform: rotate(0); }
  50% { transform: rotate(7deg); }
}
@keyframes bf-asa {
  from { transform: rotate(14deg); }
  to { transform: rotate(-44deg) scale(0.9); }
}
/* "piu-piu": a cabeça sobe um pouco e o bico abre duas vezes, depois descansa */
@keyframes bf-cabeca {
  0%, 56%, 90%, 100% { transform: rotate(0); }
  62%, 82% { transform: rotate(-6deg); }
}
@keyframes bf-bico-baixo {
  0%, 62%, 86%, 100% { transform: rotate(0); }
  66% { transform: rotate(18deg); }
  71% { transform: rotate(3deg); }
  76% { transform: rotate(15deg); }
  81% { transform: rotate(0); }
}
@keyframes bf-bico-cima {
  0%, 62%, 86%, 100% { transform: rotate(0); }
  66% { transform: rotate(-5deg); }
  71% { transform: rotate(0); }
  76% { transform: rotate(-4deg); }
  81% { transform: rotate(0); }
}
@media (prefers-reduced-motion: reduce) {
  .beija-flor .bf-borrao { display: none; }
}
"""
s=s.replace(old,new)
open(p,'w').write(s)
EOF
sed -i 's|<h1 className="vitrine-marca"><Logo tamanho={140} /></h1>|<h1 className="vitrine-marca"><Logo tamanho={140} animado /></h1>|' src/telas/Inicio.jsx && grep -n "animado" src/telas/Inicio.jsx; grep -n "port\|5180" vite.config.js; grep -n "PORT" ../server/src/*.js | head -3

