const { chromium } = require('/tmp/claude-1000/-home-edumg-hackathon-dopamine/b5795d8c-1da1-42f6-ae26-42800fd85246/scratchpad/node_modules/playwright-core');
const fs = require('fs'); const path = require('path');
(async () => {
  const exe = fs.readdirSync(process.env.HOME + '/.cache/ms-playwright').find(d => d.startsWith('chromium_headless_shell'));
  const b = await chromium.launch({ executablePath: path.join(process.env.HOME, '.cache/ms-playwright', exe, 'chrome-linux/headless_shell') });
  const p = await b.newPage({ viewport: { width: 1280, height: 760 }, deviceScaleFactor: 2 });
  await p.goto('http://127.0.0.1:5180/'); await p.waitForTimeout(1500);
  await p.screenshot({ path: process.argv[2] + '/full.png' });
  const el = await p.$('.vitrine-marca');
  // [tempo em ms] para conferir: asas no alto, asas embaixo, bico aberto
  for (const [nome, t] of [['asa-cima', 0], ['asa-baixo', 75], ['bico-aberto', 3600 * 0.66], ['bico-2', 3600 * 0.76]]) {
    await p.evaluate(t => document.querySelectorAll('.beija-flor *').forEach(e => e.getAnimations().forEach(a => { a.pause(); a.currentTime = t; })), t);
    await el.screenshot({ path: `${process.argv[2]}/${nome}.png` });
  }
  await b.close();
})();
