.link-voltar { align-self: flex-start; display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 12px 0 6px; border: none; border-radius: 10px; background: none; color: var(--verde-forte); font-weight: 700; text-decoration: none; }
.link-voltar:hover { background: var(--verde-claro); }

/* ---------------------------------------------------------------- Página inicial (vitrine) */
.inicio { min-height: 100dvh; display: flex; flex-direction: column; background: var(--papel); }
.inicio-topo { position: relative; z-index: 3; display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 14px clamp(16px, 4vw, 48px); background: var(--papel); border-bottom: 1px solid var(--borda); }
.inicio-topo .botao { min-height: 52px; padding: 0 22px; border-radius: 14px; }
.botao.primario { background: var(--verde-forte); border-color: var(--verde-forte); color: #fff; }
.botao.primario:hover { background: var(--tinta); border-color: var(--tinta); }
.vitrine { position: relative; flex: 1; min-height: 560px; overflow: hidden; display: grid; place-items: center; }
.fileiras { position: absolute; inset: -40px 0; display: flex; flex-direction: column; justify-content: center; gap: 18px; transform: rotate(-4deg) scale(1.08); }
.fileira { overflow: hidden; }
.fileira-trilho { display: flex; gap: 18px; width: max-content; animation: rolar 90s linear infinite reverse; }
.fileira.para-esquerda .fileira-trilho { animation-direction: normal; animation-duration: 110s; }
.inicio.pausado .fileira-trilho { animation-play-state: paused; }
@keyframes rolar { from { transform: translateX(0); } to { transform: translateX(calc(-50% - 9px)); } }
.capa { position: relative; flex: none; width: 260px; height: 168px; border-radius: 18px; overflow: hidden; background: var(--ceu); }
.capa-chao { position: absolute; left: -10%; right: -10%; bottom: -30px; height: 96px; border-radius: 50% 50% 0 0; background: var(--chao); }
.capa-item { position: absolute; right: 14px; top: 10px; width: 92px; height: 92px; }
.capa-personagem { position: absolute; left: 10px; top: 8px; width: 84px; height: 84px; }
.capa-rodape { position: absolute; left: 10px; right: 10px; bottom: 10px; display: flex; align-items: center; gap: 10px; padding: 6px 12px 6px 6px; border-radius: 12px; background: rgba(255, 255, 255, 0.92); }
.capa-rodape img { flex: none; width: 36px; height: 36px; border-radius: 9px; object-fit: contain; }
.capa-rodape span { display: flex; flex-direction: column; line-height: 1.15; min-width: 0; }
.capa-rodape strong { font-family: var(--titulo); font-weight: 600; color: var(--tinta); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.capa-rodape small { color: var(--suave); font-size: 0.8rem; }
/* Marca no centro: sem caixa, só uma sombra escura e esfumada atrás para destacar das capas. */
.vitrine-marca { position: relative; z-index: 2; margin: 0; display: grid; place-items: center; }
.vitrine-marca::before { content: ''; position: absolute; inset: -60% -35%; z-index: -1; border-radius: 50%; background: radial-gradient(closest-side, rgba(0, 0, 0, 0.85), rgba(0, 0, 0, 0.65) 45%, rgba(0, 0, 0, 0)); filter: blur(10px); }
.vitrine-marca .logo { font-size: clamp(72px, 13vw, 168px) !important; filter: drop-shadow(0 4px 14px rgba(0, 0, 0, 0.35)); }
.vitrine-pausa { position: absolute; z-index: 2; right: 16px; bottom: 16px; border: none; background: rgba(255, 255, 255, 0.92); }

