    drop-shadow(0 0.05em 0 rgba(30, 59, 47, 0.55)) drop-shadow(0 0.12em 0.18em rgba(30, 59, 47, 0.35)); }
"""
s=s[:a]+new+s[b:]
open(p,'w').write(s)
EOF
