cd /home/edumg/hackathon-dopamine-worktrees/eduardo-beija-flor/site/web && python3 - <<'EOF'
p='src/estilo.css'
s=open(p).read()
a=s.index("/* Beija-flor animado da capa")
b=s.index("@media (prefers-reduced-motion: reduce) {\n  .beija-flor")
CICLO=4000  # ms
pct=lambda ms: f"{ms/CICLO*100:.3g}%"
# asas: batidas de 75 ms durante o primeiro segundo, começando e terminando na pose de descanso
asa=[f"  0%, {pct(1000)}, 100% {{ transform: rotate(0); }}"]
t,baixo=40,True
while t<=960:
    asa.append(f"  {pct(t)} {{ transform: {'rotate(-44deg) scale(0.9)' if baixo else 'rotate(14deg)'}; }}")
    t+=75; baixo=not baixo
asa='\n'.join(asa)
new=f"""/* Beija-flor animado da capa (Logo animado): a cada 4 s ele se mexe por 1 s e fica 3 s parado.
   Os transform-origin estão em unidades do viewBox do SVG: raiz de cada asa, dobradiça do bico,
   pescoço e base da cauda. */
.beija-flor * {{ animation-duration: 4s; animation-iteration-count: infinite; animation-timing-function: ease-in-out; }}
.beija-flor .bf-corpo {{ transform-origin: 100px 120px; animation-name: bf-flutuar; }}
.beija-flor .bf-rastros {{ animation-name: bf-rastros; }}
.beija-flor .bf-cauda {{ transform-origin: 80px 146px; animation-name: bf-cauda; }}
.beija-flor .bf-asa {{ animation-name: bf-asa; }}
.beija-flor .bf-asa-frente, .beija-flor .bf-borrao {{ transform-origin: 106px 114px; }}
.beija-flor .bf-asa-tras {{ transform-origin: 95px 110px; animation-delay: -0.03s; }}
.beija-flor .bf-borrao {{ opacity: 0; animation-name: bf-borrao; }}
.beija-flor .bf-borrao-cima {{ transform: rotate(14deg); }}
.beija-flor .bf-borrao-baixo {{ transform: rotate(-44deg) scale(0.9); }}
.beija-flor .bf-cabeca {{ transform-origin: 138px 104px; animation-name: bf-cabeca; }}
.beija-flor .bf-bico-baixo {{ transform-origin: 166px 86px; animation-name: bf-bico-baixo; }}
.beija-flor .bf-bico-cima {{ transform-origin: 165px 80px; animation-name: bf-bico-cima; }}
.inicio.pausado .beija-flor * {{ animation-play-state: paused; }}

/* 25% do ciclo = 1 s de movimento; de 25% a 100% tudo fica na pose de descanso */
@keyframes bf-flutuar {{
  0%, 25%, 100% {{ transform: translateY(0) rotate(0); }}
  12.5% {{ transform: translateY(-6px) rotate(-2.5deg); }}
}}
@keyframes bf-rastros {{
  0%, 25%, 100% {{ transform: translateX(0); opacity: 1; }}
  12.5% {{ transform: translateX(-5px); opacity: 0.45; }}
}}
@keyframes bf-cauda {{
  0%, 25%, 100% {{ transform: rotate(0); }}
  12.5% {{ transform: rotate(7deg); }}
}}
@keyframes bf-asa {{
{asa}
}}
/* rastros das asas só aparecem enquanto elas batem */
@keyframes bf-borrao {{
  0%, 25%, 100% {{ opacity: 0; }}
  2%, 23% {{ opacity: 0.22; }}
}}
/* "piu-piu": a cabeça sobe um pouco e o bico abre duas vezes */
@keyframes bf-cabeca {{
  0%, 25%, 100% {{ transform: rotate(0); }}
  5%, 20% {{ transform: rotate(-6deg); }}
}}
@keyframes bf-bico-baixo {{
  0%, 5%, 20%, 100% {{ transform: rotate(0); }}
  8.75% {{ transform: rotate(18deg); }}
  12.5% {{ transform: rotate(3deg); }}
  16.25% {{ transform: rotate(15deg); }}
}}
@keyframes bf-bico-cima {{
  0%, 5%, 20%, 100% {{ transform: rotate(0); }}
  8.75% {{ transform: rotate(-5deg); }}
  12.5% {{ transform: rotate(0); }}
  16.25% {{ transform: rotate(-4deg); }}
}}
"""
s=s[:a]+new+s[b:]
open(p,'w').write(s)
EOF
sed -n '/@keyframes bf-asa/,/^}/p' src/estilo.css | head -20; grep -n "bf-borrao { display" src/estilo.css

