cd /home/edumg/hackathon-dopamine/site/web && cat > public/_gif.html <<'E'
<!doctype html><html><body style="margin:0;overflow:hidden">
<script>
// ?t=segundos — monta um quadro do GIF da tela inicial (temporário, não vai para o git)
const q = new URLSearchParams(location.search)
const t = Number(q.get('t'))
const fundo = q.get('fundo') ?? '3'
const centro = q.get('centro') ?? '20'
const f = document.createElement('iframe')
f.width = 1920; f.height = 1080; f.style.border = 0
f.src = '/'
f.onload = () => setTimeout(() => {
  const d = f.contentDocument
  const css = d.createElement('style')
  css.textContent = `
    .vitrine-pausa { display: none !important; }
    .fileiras { filter: blur(${fundo}px); }
    .vitrine::before {
      -webkit-backdrop-filter: blur(${centro}px) !important; backdrop-filter: blur(${centro}px) !important;
      -webkit-mask-image: radial-gradient(ellipse 62% 56% at 50% 50%, #000 45%, transparent 100%) !important;
      mask-image: radial-gradient(ellipse 62% 56% at 50% 50%, #000 45%, transparent 100%) !important;
    }`
  d.head.append(css)
  const PASSO = 278, CICLO = 3, AVE = 0.75
  for (const a of d.getAnimations()) {
    a.pause()
    const el = a.effect.target
    if (a.animationName === 'rolar') {
      const dur = a.effect.getTiming().duration
      const dist = (el.scrollWidth + 18) / 2
      const p = (0.3 + (PASSO * t) / CICLO / dist) % 1
      a.currentTime = p * dur
    } else if (el.closest && el.closest('.beija-flor')) {
      a.currentTime = ((t % AVE) / AVE) * 800
    }
  }
  document.title = 'pronto'
}, 1500)
document.body.append(f)
</script>
</body></html>
E
